import React from 'react';
import { useHistory } from 'react-router-dom';
import CustomButton from 'components/CustomButton';
import constants from 'config/constants';
import { getGlobalSchoolUtils, getLoggedUserUtils } from 'utils/commonFunc';
import EmptyState from './EmptyState';

// What a page shows for a school that has no academic year (batch) yet - a brand-new school. Instead of an endless loader or a
// bare line of text: a clear card, and for the super admin / admin a button to School setup. `what` names what is missing.
const SetupNeeded = ({ what = 'academic year' }) => {
  const history = useHistory();
  const role = getLoggedUserUtils()?.userRole;
  // setting a school up is the super admin's job (it opens from the Schools page)
  const canSetUp = role === constants.roles.SA;

  return (
    <div className="content">
      <EmptyState
        icon="fas fa-magic"
        title={`This school has no ${what} yet`}
        subtitle={
          canSetUp
            ? 'Do the school setup first: the school admin, the batch with its classes and subjects, and the staff.'
            : 'Ask the super admin to finish the school setup first.'
        }
      />
      {canSetUp && (
        <div style={{ textAlign: 'center', marginTop: 16 }}>
          <CustomButton
            name="Start school setup"
            onClick={() =>
              history.push(`/admin/schools/${getGlobalSchoolUtils()?.schoolId}/setup`, {
                schoolName: getGlobalSchoolUtils()?.schoolName,
              })
            }
          />
        </div>
      )}
    </div>
  );
};

export default SetupNeeded;
