import React, { useState } from 'react';
import moment from 'moment';
import colors from 'config/colors';
import TimelineAvatar from './TimelineAvatar';

const toLine = text => `${text || ''}`.replace(/\s+/g, ' ').trim();

const PostRow = ({ post, authorLabel, selected, onOpen }) => {
  const [hover, setHover] = useState(false);
  const photos = (post.media || []).filter(m => m.mediaType !== 'VIDEO').length;
  const videos = (post.media || []).length - photos;
  return (
    <div
      role="button"
      tabIndex={0}
      onClick={onOpen}
      onKeyDown={e => (e.key === 'Enter' || e.key === ' ') && onOpen()}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        display: 'flex',
        alignItems: 'center',
        gap: 12,
        padding: '10px 14px',
        cursor: 'pointer',
        borderBottom: '1px solid #f0eaf5',
        borderLeft: `3px solid ${selected ? colors.accent : 'transparent'}`,
        background: selected ? colors.sidebarActiveItemBg : hover ? colors.sidebarBg : colors.white,
        transition: 'background .15s',
      }}>
      <TimelineAvatar name={authorLabel} size={36} />
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: 8 }}>
          <span style={{ fontWeight: 'bold', fontSize: 14, color: colors.grey1, whiteSpace: 'nowrap' }}>
            {authorLabel}
          </span>
          <span style={{ fontSize: 11.5, color: colors.grey3, whiteSpace: 'nowrap' }}>
            {post.creationDateTime ? moment(post.creationDateTime).fromNow() : ''}
          </span>
        </div>
        <div
          style={{
            fontSize: 12.5,
            color: colors.grey3,
            marginTop: 2,
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap',
          }}>
          {toLine(post.content) || 'Photos / videos'}
        </div>
      </div>
      {!!(photos || videos) && (
        <span
          style={{
            flexShrink: 0,
            fontSize: 12,
            fontWeight: 'bold',
            color: colors.accent,
            background: `${colors.accent}14`,
            borderRadius: 12,
            padding: '2px 10px',
          }}>
          <i className={videos && !photos ? 'fas fa-video' : 'far fa-image'} style={{ marginRight: 5 }} />
          {photos + videos}
        </span>
      )}
    </div>
  );
};

// The posts of the chosen class, newest first, one compact row each; the open one is highlighted.
const TimelinePostList = ({ posts, selectedId, authorLabel, onSelect, hasMore, loadingMore, onLoadMore }) => (
  <>
    {posts.map(post => (
      <PostRow
        key={post.postId}
        post={post}
        authorLabel={authorLabel(post)}
        selected={post.postId === selectedId}
        onOpen={() => onSelect(post.postId)}
      />
    ))}
    {hasMore && (
      <div style={{ padding: 12, textAlign: 'center' }}>
        <button
          type="button"
          disabled={loadingMore}
          onClick={onLoadMore}
          style={{
            border: `1px solid ${colors.accent}`,
            background: '#fff',
            color: colors.accent,
            borderRadius: 18,
            padding: '5px 22px',
            fontSize: 13,
            fontWeight: 'bold',
            cursor: loadingMore ? 'default' : 'pointer',
            opacity: loadingMore ? 0.6 : 1,
          }}>
          {loadingMore ? 'Loading...' : 'View more'}
        </button>
      </div>
    )}
  </>
);

export default TimelinePostList;
